53	  Future<shelf.Response> handle(shelf.Request request) async {
54	    if (request.method != 'GET') {
55	      // Assets are served via GET only.
56	      return shelf.Response.notFound('');
57	    }
58	
59	    Uri? fileUri;
60	    final String? requestPath = stripBasePath(request.url.path, basePath);
61	
62	    if (requestPath == null) {
63	      return shelf.Response.notFound('');
64	    }
65	
66	    if (request.url.toString() == 'main.dart') {
67	      fileUri = entrypoint;
68	    } else {
69	      for (final Uri uri in _searchPaths()) {
70	        final Uri potential = uri.resolve(requestPath);
71	        if (_fileSystem.isFileSync(potential.toFilePath(windows: _platform.isWindows))) {
72	          fileUri = potential;
73	          break;
74	        }
75	      }
76	    }
77	    if (fileUri != null) {
78	      final File file = _fileSystem.file(fileUri);
79	      final Uint8List bytes = file.readAsBytesSync();
80	      // Fallback to "application/octet-stream" on null which
81	      // makes no claims as to the structure of the data.
82	      final String mimeType =
83	          mime.lookupMimeType(file.path, headerBytes: bytes) ?? 'application/octet-stream';
84	      return shelf.Response.ok(
85	        bytes,
86	        headers: <String, String>{
87	          'Content-Type': mimeType,
88	          'Cross-Origin-Resource-Policy': 'cross-origin',
89	          'Access-Control-Allow-Origin': '*',
90	          if (_needsCoopCoep && _fileSystem.path.extension(file.path) == '.html')
91	            ...kCrossOriginIsolationHeaders,
92	        },
93	      );
94	    }
95	
96	    final File file = _fileSystem.file(_fileSystem.path.join(_webBuildDirectory!, 'index.html'));
97	    return shelf.Response.ok(
98	      file.readAsBytesSync(),
99	      headers: <String, String>{
100	        'Content-Type': 'text/html',
101	        if (_needsCoopCoep) ...kCrossOriginIsolationHeaders,
102	      },
103	    );
104	  }
